local b=bit32.bxor
local s=string.char
local n=tonumber
local c=table.concat
local h=''
local k={28,74,177,94,122,194,229,163,251,25,171,148,102,246,136,114,131,55,33,237,255,160,212,221,125,224,200,106,252,192,159,235}
local o={}
local i=1
local p=0
while i<=#h do
 p+=1
 o[p]=s(b(n(h:sub(i,i+1),16),k[(p-1)%#k+1]))
 i+=2
end
return (loadstring or load)(c(o))()
